TEST(format_test, zero_flag_and_align) {
  // If the 0 character and an align option both appear, the 0 character is ignored.
  EXPECT_EQ("42   ", fmt::format("{0:<05}", 42));
  EXPECT_EQ("-42  ", fmt::format("{0:<05}", -42));
  EXPECT_EQ(" 42  ", fmt::format("{0:^05}", 42));
  EXPECT_EQ(" -42 ", fmt::format("{0:^05}", -42));
  EXPECT_EQ("   42", fmt::format("{0:>05}", 42));
  EXPECT_EQ("  -42", fmt::format("{0:>05}", -42));
}

